<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Customer\Support\Security;

use Module\Customer\Action\Enum\CustomerStatusEnum;
use Module\Customer\Model\Customer;
use Module\Customer\Support\CustomerBag;
use Module\Customer\Support\Security\CustomerProvider;
use Module\Shared\Exception\AppUnauthorizedException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\Security\Core\Exception\UnsupportedUserException;
use Symfony\Component\Security\Core\User\UserInterface;
use Tests\UnitTestCase;

class CustomerProviderTest extends UnitTestCase
{
    private CustomerProvider $sut;

    private CustomerBag $customerBag;

    public function setUp(): void
    {
        parent::setUp();

        $this->customerBag = new CustomerBag();

        $this->sut = new CustomerProvider(
            $this->customerBag
        );
    }

    /**
     * @param array<string, int>|null $bagData
     */
    #[Test, DataProvider('dataProviderLoadUserByIdentifier')]
    public function loadUserByIdentifier(
        ?array $bagData,
        string $identifier,
        string $expectedExceptionMessage,
        ?int $expectedId,
        int $expectedStoreId,
    ): void {
        if ($bagData) {
            $this->customerBag->customerId = $bagData['customerId'];
            $this->customerBag->selectedStoreId = $bagData['selectedStoreId'];
        }

        if ($expectedExceptionMessage) {
            $this->expectException(AppUnauthorizedException::class);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->loadUserByIdentifier($identifier);

        $this->assertInstanceOf(Customer::class, $result);
        $this->assertSame($expectedId, $result->getId());
        $this->assertSame($expectedStoreId, $result->getSelectedStore());
        $this->assertSame(CustomerStatusEnum::ACTIVE, $result->getStatus());
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderLoadUserByIdentifier(): array
    {
        return [
            'not authenticated' => [
                'bagData' => null,
                'identifier' => '5',
                'expectedExceptionMessage' => 'Customer is not authenticated.',
                'expectedId' => null,
                'expectedStoreId' => 0,
            ],
            'identifier mismatch' => [
                'bagData' => ['customerId' => 7, 'selectedStoreId' => 0],
                'identifier' => '5',
                'expectedExceptionMessage' => 'Unexpected customer identifier.',
                'expectedId' => null,
                'expectedStoreId' => 0,
            ],
            'success' => [
                'bagData' => ['customerId' => 5, 'selectedStoreId' => 10],
                'identifier' => '5',
                'expectedExceptionMessage' => '',
                'expectedId' => 5,
                'expectedStoreId' => 10,
            ],
        ];
    }

    #[Test, DataProvider('dataProviderRefreshUser')]
    public function refreshUser(
        bool $isCustomer,
        bool $expectedException,
    ): void {
        $user = $isCustomer
            ? Customer::factory('', 0, CustomerStatusEnum::ACTIVE, 1)
            : $this->createStub(UserInterface::class);

        if ($expectedException) {
            $this->expectException(UnsupportedUserException::class);
        }

        $result = $this->sut->refreshUser($user);

        $this->assertSame($user, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderRefreshUser(): array
    {
        return [
            'success' => [
                'isCustomer' => true,
                'expectedException' => false,
            ],
            'unsupported class' => [
                'isCustomer' => false,
                'expectedException' => true,
            ],
        ];
    }

    #[Test, DataProvider('dataProviderSupportsClass')]
    public function supportsClass(
        string $class,
        bool $expected,
    ): void {
        $this->assertSame($expected, $this->sut->supportsClass($class));
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderSupportsClass(): array
    {
        return [
            'customer class' => [
                'class' => Customer::class,
                'expected' => true,
            ],
            'other class' => [
                'class' => \stdClass::class,
                'expected' => false,
            ],
        ];
    }
}
